"""Offline original roof references and additional cardinal elevation crops."""
import argparse
import base64
import gzip
import json
from pathlib import Path

import pymupdf
from PIL import Image

from voxel_mapper.drawing_page_tools import native_inverse
from voxel_mapper.generation_cycles import file_hash


def render(evidence, views, corpus, output):
    evidence, views, corpus, output = map(Path, (evidence, views, corpus, output))
    path = evidence / 'roof-reference-evidence.json'; raw = path.read_bytes(); result = json.loads(raw)
    if result['status'] != 'roof_reference_evidence_only': raise ValueError('Complete roof-reference evidence required')
    if file_hash(views / 'view-report.json') != result['contract']['view_report_sha256']:
        raise ValueError('Original source views changed')
    report = json.loads((views / 'view-report.json').read_text())
    for name, pin in report['output_sha256'].items():
        if file_hash(views / name) != pin: raise ValueError('Original source view artifact changed')
    for name, pin in result['output_artifact_sha256'].items():
        if file_hash(evidence / name) != pin: raise ValueError('Additional source view artifact changed')
    originals = {v['id']: v for p in json.loads((views / 'view-candidates.json').read_text())['pages'] for v in p['views']}
    payload = {'review_sha256': file_hash(path), 'gzip_json': base64.b64encode(gzip.compress(raw, mtime=0)).decode(),
        'images': {}, 'roof_pages': {}}
    def image(key, png, receipt, caption):
        with Image.open(png) as im: size = list(im.size)
        payload['images'][key] = {'caption': caption, 'size': size, 'sha256': file_hash(png),
            'native_to_pixel_matrix': list(~pymupdf.Matrix(receipt['pixel_edge_to_pdf_native_matrix'])),
            'png': 'data:image/png;base64,' + base64.b64encode(png.read_bytes()).decode()}
    for page in result['roof_page_references']:
        key = page['view_id']; view = originals[key]; receipt = json.loads((views / view['render']['receipt']).read_text())
        image(key, views / view['render']['png'], receipt, view['caption_text'])
        original = corpus / 'files' / (page['document_sha256'] + '.pdf')
        if file_hash(original) != page['document_sha256']: raise ValueError('Original roof PDF changed')
        with pymupdf.open(original) as doc: matrix = native_inverse(doc[page['page'] - 1])
        payload['roof_pages'][key] = {'page_to_pixel_matrix': list(matrix * ~pymupdf.Matrix(receipt['pixel_edge_to_pdf_native_matrix']))}
    for view in result['rendered_views']:
        receipt = json.loads((evidence / view['receipt']).read_text())
        image(view['view_id'], evidence / view['png'], receipt, view['caption'])
    html = r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Preshow drawing references</title>
<style>body{margin:0;background:#eff3f5;color:#183542;font:16px system-ui}main{max-width:1400px;padding:28px;margin:auto}h1{font-size:32px}h2{font-size:20px}.small{font-size:13px;color:#526d79}p{line-height:1.5}.notice{padding:16px;background:#fff0cd;border-left:4px solid #a87813}.metrics,.panels{display:grid;gap:18px;margin:22px 0}.metrics{grid-template-columns:repeat(4,1fr)}.panels{grid-template-columns:1fr 1fr}article,.metric{border:1px solid #d4dfe5;background:white;border-radius:8px;padding:18px}.metric b{display:block;font-size:29px}.controls{display:flex;flex-wrap:wrap;gap:16px}label{font-size:14px}select,button{font:inherit;padding:8px;margin:6px 0;display:block;max-width:100%;border:1px solid #92a8b5;border-radius:4px;background:white}button{background:#16495e;color:white;cursor:pointer}svg{width:100%;height:420px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:9px;border-bottom:1px solid #dae3e8;text-align:left}td{word-break:break-word}pre{white-space:pre-wrap;font-size:12px}details{margin:20px 0}summary{padding:12px;font-weight:600;cursor:pointer}@media(max-width:850px){.panels,.metrics{grid-template-columns:1fr}main{padding:16px}}</style>
<main><div class="small">VOXEL MAPPER / ADDITIONAL ORIGINAL SOURCE</div><h1>Roof references → preshow elevations</h1><p>The retained official preshow attachment was reacquired and matches its recorded SHA-256. Numbered cardinal captions and original side-arrow outlines now provide source-key links to the additional drawings.</p><p class="notice">Sheet-reference numbers are not roof pitches. Source-key matches and symbol-aim diagnostics do not establish physical building identity or permit geometry. Split level labels, eave/ridge measurements, source tails and complete depth still need source-bound handling. No new mesh or world placement.</p><div class="metrics" id="metrics"></div>
<div class="controls"><label>Original roof reference<select id="reference"></select></label><label>Connected plan-line candidate<select id="candidate"></select></label><label>Additional source view<select id="view"></select></label></div><div class="controls"><label><input type="checkbox" id="full"> Full original roof crop</label><label><input type="checkbox" id="aim" checked> Show bounded symbol-aim diagnostic</label><button id="download">Export full evidence JSON</button></div><p id="status"></p>
<div class="panels"><article><h2>Original roof marker & connected line candidate</h2><svg id="plan"></svg><p class="small">Magenta: original circle and both whole V-outline arms. Gold: candidate ridge. Blue: whole original rails, including tails. Dashed violet: diagnostic aim, extended two symbol radii beyond the original tip; it is not a source stroke or physical boundary.</p></article><article><h2 id="caption"></h2><svg id="elevation"></svg><p id="view-status" class="small"></p></article></div>
<article><h2>Exact drawing keys · all source references</h2><div style="overflow:auto"><table><thead><tr><th>Sheet / view</th><th>Reference status</th><th>Target availability</th><th>Physical identity</th></tr></thead><tbody id="links"></tbody></table></div></article>
<details><summary>Original head strokes and glyph-screen receipts</summary><pre id="marker"></pre></details><details><summary>Staggered caption-row evidence</summary><pre id="rows"></pre></details><details><summary>Current source-annotation limits</summary><p>The original preshow drawing contains Preshow Top Level +183.30. The current generic single-line annotation grammar does not bind this split label to its marker. A visible value alone is not a measured eave height or an accepted floor/vertical datum. Existing source and glyph holds remain intact.</p></details><p id="hash" class="small"></p></main><script type="application/json" id="data">PAYLOAD</script><script>
const packed=JSON.parse(document.getElementById('data').textContent),byId=id=>document.getElementById(id),ns='http://www.w3.org/2000/svg';let data,raw,state;
function option(select,value,label){let o=document.createElement('option');o.value=value;o.textContent=label;select.append(o)}function node(tag,attrs,parent){let e=document.createElementNS(ns,tag);for(let[k,v]of Object.entries(attrs))e.setAttribute(k,v);parent.append(e);return e}function point(p,m){return[p[0]*m[0]+p[1]*m[2]+m[4],p[0]*m[1]+p[1]*m[3]+m[5]]}function source(svg,im,bounds){svg.replaceChildren();svg.setAttribute('viewBox',bounds.join(' '));node('image',{href:im.png,x:0,y:0,width:im.size[0],height:im.size[1]},svg)}
function draw(){let ref=data.references.find(r=>r.id===byId('reference').value),link=data.evidence.target_links.find(l=>l.source_reference_id===ref.id),candidate=data.candidates.find(c=>c.id===byId('candidate').value),top=data.evidence.source_topologies.find(t=>t.candidates.some(c=>c.id===candidate.id)),lines=new Map(top.lines.map(l=>[l.source_component_id,l])),page=data.evidence.roof_page_references.find(p=>p.side_reference_review.references.some(r=>r.id===ref.id)),im=packed.images[page.view_id],m=packed.roof_pages[page.view_id].page_to_pixel_matrix,n=im.native_to_pixel_matrix,svg=byId('plan'),head=ref.head_alternatives[0],check=data.evidence.aim_checks.find(c=>c.candidate_id===candidate.id&&c.source_reference_id===ref.id&&c.head_alternative_index===0),ids=[candidate.ridge_source_id,...candidate.rail_source_ids],boundsPoints=ids.flatMap(id=>lines.get(id).source_endpoints_pdf_native.map(p=>point(p,n))).concat(ref.circle_source_beziers.flatMap(c=>c.map(p=>point(p,m)))),xs=boundsPoints.map(p=>p[0]),ys=boundsPoints.map(p=>p[1]);source(svg,im,byId('full').checked?[0,0,...im.size]:[Math.min(...xs)-30,Math.min(...ys)-30,Math.max(...xs)-Math.min(...xs)+60,Math.max(...ys)-Math.min(...ys)+60]);
for(let id of ids)node('polyline',{points:lines.get(id).source_endpoints_pdf_native.map(p=>point(p,n).join(',')).join(' '),fill:'none',stroke:id===candidate.ridge_source_id?'#c38b00':'#196fa3','stroke-width':2,class:'source-plan-line','data-source-id':id},svg);let d='';for(let[i,c]of ref.circle_source_beziers.entries()){let q=c.map(p=>point(p,m));if(i===0)d+=`M${q[0].join(' ')} `;d+=`C${q.slice(1).map(p=>p.join(' ')).join(' ')} `}node('path',{d,fill:'none',stroke:'#ab388d','stroke-width':2,class:'source-circle'},svg);for(let arm of head.head_source_arms)node('polyline',{points:arm.source_endpoints_page_points.map(p=>point(p,m).join(',')).join(' '),fill:'none',stroke:'#ab388d','stroke-width':2,class:'source-arm','data-path-indices':arm.source_path_indices.join(',')},svg);if(check&&byId('aim').checked)node('polyline',{points:check.diagnostic_aim_segment_pdf_native.map(p=>point(p,n).join(',')).join(' '),fill:'none',stroke:'#7640b5','stroke-dasharray':'4 3','stroke-width':2,class:'diagnostic-aim'},svg);
let selected=data.evidence.rendered_views.find(v=>v.view_id===byId('view').value),vim=packed.images[selected.view_id],view=data.evidence.additional_pages.flatMap(p=>p.view_candidates.views).find(v=>v.id===selected.view_id);source(byId('elevation'),vim,[0,0,...vim.size]);byId('caption').textContent=selected.caption;byId('view-status').textContent=`${view.whole_sources.length} whole original source objects retained. Nominal ${view.nominal_metres_per_pdf_point.toFixed(8)} m per PDF point from this view's printed scale. Crop boundaries and scale application remain hypotheses. No building mesh is generated.`;byId('status').textContent=`${link.status.replaceAll('_',' ')} · reference ${ref.target_sheet_candidate}/${head.target_view_candidate}. ${link.target_candidates.length} exact source-key target(s). ${check?check.status.replaceAll('_',' '):'No matching plan diagnostic'}. ${link.target_candidates.some(t=>t.view_id===selected.view_id)?'The selected source view matches this drawing key.':'The selected additional view is for inspection; this reference does not uniquely select it.'}`;byId('marker').textContent=JSON.stringify({reference:ref,glyph_screens:page.side_reference_review.glyph_screens},null,2);state={ref,link,candidate,top,selected,view,check,page};}
function chooseReference(){let ref=data.references.find(r=>r.id===byId('reference').value),link=data.evidence.target_links.find(l=>l.source_reference_id===ref.id);if(link.target_candidates.length===1&&data.evidence.rendered_views.some(v=>v.view_id===link.target_candidates[0].view_id))byId('view').value=link.target_candidates[0].view_id;let good=data.evidence.aim_checks.find(c=>c.source_reference_id===ref.id&&c.positive_intersection_length_pdf_points>0);if(good)byId('candidate').value=good.candidate_id;draw()}
async function start(){raw=await new Response(new Blob([Uint8Array.from(atob(packed.gzip_json),c=>c.charCodeAt(0))]).stream().pipeThrough(new DecompressionStream('gzip'))).text();let evidence=JSON.parse(raw);data={evidence,references:evidence.roof_page_references.flatMap(p=>p.side_reference_review.references),candidates:evidence.source_topologies.flatMap(t=>t.candidates)};for(let[k,v]of[['additional_view_candidates',evidence.counts.additional_view_candidates],['side_reference_candidates',evidence.counts.side_reference_candidates],['unique_source_target_links',evidence.counts.unique_source_target_links],['source_visibility_holds',evidence.counts.source_visibility_holds]]){let div=document.createElement('div');div.className='metric';let b=document.createElement('b');b.textContent=v;div.append(b,document.createTextNode(k.replaceAll('_',' ')));byId('metrics').append(div)}for(let r of data.references)option(byId('reference'),r.id,`Sheet ${r.target_sheet_candidate} · view ${r.head_alternatives.map(h=>h.target_view_candidate).join('/')} · ${r.status.startsWith('withheld')?'held':'candidate'}`);for(let c of data.candidates)option(byId('candidate'),c.id,`${c.ridge_source_id.slice(0,12)} · ${c.nominal_ridge_length_m.toFixed(2)} m`);for(let v of evidence.rendered_views)option(byId('view'),v.view_id,v.caption);for(let link of evidence.target_links){let ref=data.references.find(r=>r.id===link.source_reference_id),tr=document.createElement('tr');for(let value of[`${ref.target_sheet_candidate} / ${ref.head_alternatives.map(h=>h.target_view_candidate).join(',')}`,ref.status.replaceAll('_',' '),link.status.replaceAll('_',' '),'Unverified']){let td=document.createElement('td');td.textContent=value;tr.append(td)}byId('links').append(tr)}byId('rows').textContent=JSON.stringify(evidence.additional_pages.flatMap(p=>p.view_candidates.caption_row_grouping_evidence),null,2);byId('hash').textContent='Evidence SHA-256: '+packed.review_sha256;let west=evidence.additional_pages.flatMap(p=>p.view_candidates.views).find(v=>v.printed_claim.direction==='west'),initial=west&&evidence.target_links.find(l=>l.target_candidates.length===1&&l.target_candidates[0].view_id===west.id);if(initial)byId('reference').value=initial.source_reference_id;byId('reference').addEventListener('change',chooseReference);for(let id of['candidate','view','full','aim'])byId(id).addEventListener('change',draw);byId('download').addEventListener('click',()=>{let url=URL.createObjectURL(new Blob([raw],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='roof-reference-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});chooseReference();document.body.dataset.ready='true'}start().catch(e=>{byId('status').textContent=String(e);throw e});
</script></html>'''.replace('PAYLOAD', json.dumps(payload, separators=(',', ':')).replace('<', '\u003c'))
    output.parent.mkdir(parents=True, exist_ok=True); output.write_text(html)
    return {'output': str(output), 'bytes': output.stat().st_size, 'source_images': len(payload['images'])}


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    for name in ('evidence', 'views', 'corpus', 'output'):
        parser.add_argument('--' + name, type=Path, required=True)
    print(json.dumps(render(**vars(parser.parse_args()))))
